    "eula_title": "【PhotoAutoCrop Pro — 最終使用者授權協議 (EULA)】",
    "eula_p1_title": "1. 授權授予 (Grant of License)：",
    "eula_p1_desc": "購買本軟體即授予您非專屬、終身使用之授權。Standard 版限 1 台裝置使用；Pro 商業版支援至多 3 台個人或工作室電腦使用，並得用於商業數位化服務。",
    "eula_p2_title": "2. 智慧財產與反逆向工程 (IP & Restrictions)：",
    "eula_p2_desc": "本軟體受國際版權法保護。未經書面許可，嚴禁對本軟體進行反向工程、反編譯、反組譯、二次打包、轉售或公開散布授權金鑰。",
    "eula_p3_title": "3. 零雲端隱私保障 (Zero-Cloud Privacy Guarantee)：",
    "eula_p3_desc": "本軟體於本機離線執行影像辨識與透視校正，相片資料不傳送至外部伺服器。",
    "eula_p4_title": "4. 30 天滿意保證 (Refund Policy)：",
    "eula_p4_desc": "若遭遇無法排除之相容性問題，依 Gumroad 官方政策享有 30 天內退款服務保障。",
    "privacy_title": "【PhotoAutoCrop Pro — 隱私權政策 (Privacy Policy)】",
    "privacy_p1_title": "1. 資料隱私原則 (Privacy Policy)：",
    "privacy_p1_desc": "相簿數位化涉及家庭個人回憶，本軟體架構採用本地端優先 (Local-First) 與零雲端外洩 (Zero-Cloud Leak) 原則。",
    "privacy_p2_title": "2. 零相片上傳 (Zero Photo Upload)：",
    "privacy_p2_desc": "所有相片辨識、Otsu 二值化、透視變換與 HEIC 轉碼皆透過本機 CPU / WebAssembly 處理。您的相片永不離開您的電腦。",
    "privacy_p3_title": "3. 零資料收集與無追蹤 (No Telemetry)：",
    "privacy_p3_desc": "本軟體不包含任何 Google Analytics、Sentry 或第三方使用者追蹤代碼。",
    "privacy_p4_title": "4. 授權驗證與 Gemini 選配：",
    "privacy_p4_desc": "- Gumroad 驗證透過安全 HTTPS 直接連線至官方 API，驗證後產生 30 天離線憑證。\n- 若您配置 Google Gemini AI 金鑰，API 呼叫直接從您的本機發送至 Google 官方端點，無中間代理伺服器。",
