    "guide_step1_title": "整批匯入翻拍照",
    "guide_step1_desc": "直接拖曳翻拍相片或整個資料夾進工作台。原生支援 iPhone HEIC/HEIF 格式，自動在本地完成解碼。",
    "guide_step2_title": "一鍵自動邊界識別",
    "guide_step2_desc": "點選「批次辨識」或快速鍵，視覺演算法自動定位各相片實體四角邊界。",
    "guide_step3_title": "拖曳微調與智慧吸附",
    "guide_step3_desc": "若相片幾何傾斜，拖曳 4 個角點即可調整透視；支援邊界吸附演算法輔助精確貼合。",
    "guide_step4_title": "透視校正與打包匯出",
    "guide_step4_desc": "點選「匯出 ZIP」或「儲存至資料夾」，系統自動執行透視拉平校正，並寫入 300 DPI 印刷密度標籤。",
    "guide_tip1_title": "技巧一：底紙與背景產生強烈對比",
    "guide_tip1_desc": "相片若偏白或亮色，建議放置於黑色/深色卡紙上翻拍；若相片偏暗或黑色邊框，請使用白色底紙。高對比背景有助於提高邊緣偵測與幾何擬合的準確度。",
    "guide_tip2_title": "技巧二：45 度側面光源，防止反光",
    "guide_tip2_desc": "翻拍亮面相紙或塑膠保護膜時，避免上方單一強光直射。建議使用雙側 45 度對稱光源或柔光漫射，以降低表面鏡面反射。",
    "guide_tip3_title": "技巧三：鏡頭保持水平平行垂直",
    "guide_tip3_desc": "手機或相機鏡頭盡量與翻拍桌面保持平行，減少光學視差產生的梯形畸變，有助於保留最佳有效像素解析度。",
    "guide_tip4_title": "技巧四：多張翻拍時照片間保留留白",
    "guide_tip4_desc": "單頁翻拍多張相片時，照片之間建議保留 1~2 公分間隔，避免邊界重疊，以利演算法獨立分割。",
