    "guide_step1_title": "整批导入翻拍照",
    "guide_step1_desc": "直接拖拽翻拍相片或整个文件夹进工作台。原生支持 iPhone HEIC/HEIF 格式，自动在本地完成解码。",
    "guide_step2_title": "一键自动边界识别",
    "guide_step2_desc": "点击「批处理识别」或快捷键，视觉算法自动定位各相片实体四角边界。",
    "guide_step3_title": "拖拽微调与智能吸附",
    "guide_step3_desc": "若相片几何倾斜，拖拽 4 个角点即可调整透视；支持边界吸附算法辅助精确贴合。",
    "guide_step4_title": "透视校正与打包导出",
    "guide_step4_desc": "点击「导出 ZIP」或「储存至文件夹」，系统自动执行透视拉平校正，并写入 300 DPI 印刷密度标签。",
    "guide_tip1_title": "技巧一：底纸与背景产生强烈对比",
    "guide_tip1_desc": "相片若偏白或亮色，建议放置于黑色/深色卡纸上翻拍；若相片偏暗或黑色边框，请使用白色底纸。高对比背景有助于提高边缘侦测与几何拟合的准确度。",
    "guide_tip2_title": "技巧二：45 度侧面光源，防止反光",
    "guide_tip2_desc": "翻拍亮面相纸或塑料保护膜时，避免上方单一强光直射。建议使用双侧 45 度对称光源或柔光漫射，以降低表面镜面反射。",
    "guide_tip3_title": "技巧三：镜头保持水平平行垂直",
    "guide_tip3_desc": "手机或相机镜头尽量与翻拍桌面保持平行，减少光学视差产生的梯形畸变，有助于保留最佳有效像素分辨率。",
    "guide_tip4_title": "技巧四：多张翻拍时照片间保留留白",
    "guide_tip4_desc": "单页翻拍多张相片时，照片之间建议保留 1~2 公分间隔，避免边界重叠，以利算法独立分割。",
