class I18nManager {
  constructor() {
    this.currentLocale = this.detectLocale();
  }

  init() {
    this.currentLocale = this.detectLocale();
    this.applyToDOM();
    return this;
  }

  setLanguage(locale) {
    return this.setLocale(locale);
  }

  getLanguage() {
    return this.getLocale();
  }

  detectLanguage(langInput) {
    const raw = (langInput || (typeof navigator !== 'undefined' ? (navigator.language || navigator.userLanguage) : '') || 'en').toLowerCase();
    if (raw.includes('zh-cn') || raw.includes('zh-hans') || raw.includes('zh-sg')) {
      return 'zh-CN';
    }
    if (raw.includes('zh')) {
      return 'zh-TW';
    }
    if (raw.includes('ja')) {
      return 'ja';
    }
    if (raw.includes('de')) {
      return 'de';
    }
    if (raw.includes('fr')) {
      return 'fr';
    }
    if (raw.includes('es')) {
      return 'es';
    }
    return 'en';
  }

  detectLocale() {
    const saved = typeof localStorage !== 'undefined' ? localStorage.getItem('photoautocrop_locale') : null;
    if (saved && I18N_LOCALES[saved]) return saved;
    return this.detectLanguage();
  }

  setLocale(locale) {
    if (!I18N_LOCALES[locale]) return;
    this.currentLocale = locale;
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem('photoautocrop_locale', locale);
    }
    this.applyToDOM();
    if (typeof document !== 'undefined' && document.documentElement) {
      document.documentElement.lang = locale;
    }
    // 🌐 派發全局語言變更事件，通知所有動態 UI、通知與標籤即時更新
    if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent('languageChanged', { detail: { locale, lang: locale } }));
    }
  }

  getLocale() {
    return this.currentLocale;
  }

  t(key, params = {}) {
    const dict = I18N_LOCALES[this.currentLocale] || I18N_LOCALES['en'] || {};
    let text = dict[key] || I18N_LOCALES['en']?.[key] || key;
    if (params && typeof params === 'object') {
      for (const [k, v] of Object.entries(params)) {
        text = text.replace(new RegExp('\\{' + k + '\\}', 'g'), () => String(v));
      }
    }
    return text;
  }

  applyToDOM() {
    if (typeof document === 'undefined') return;

    // 1. 動態更新視窗標題 (Window Title) 與 Electron 原生視窗標題列
    const appTitle = this.t('app_window_title');
    if (appTitle) {
      if (typeof document !== 'undefined') {
        document.title = appTitle;
      }
      if (typeof window !== 'undefined' && window.electronAPI && typeof window.electronAPI.setTitle === 'function') {
        window.electronAPI.setTitle(appTitle);
      }
    }

    // 2. 替換文字內容 [data-i18n]
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (key) {
        el.textContent = this.t(key);
      }
    });

    // 3. 替換 Placeholder [data-i18n-placeholder]
    const placeholders = document.querySelectorAll('[data-i18n-placeholder]');
    placeholders.forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      if (key) {
        el.placeholder = this.t(key);
      }
    });

    // 4. 替換 Tooltip / Title [data-i18n-title]
    const titles = document.querySelectorAll('[data-i18n-title]');
    titles.forEach(el => {
      const key = el.getAttribute('data-i18n-title');
      if (key) {
        el.title = this.t(key);
      }
    });

    // 5. 即時更新頂部快捷語言切換按鈕文字
    const langLabelMap = {
      'zh-TW': '繁體中文',
      'zh-CN': '简体中文',
      'en': 'English',
      'ja': '日本語',
      'de': 'Deutsch',
      'fr': 'Français',
      'es': 'Español'
    };
    const currentLangLabel = document.getElementById('currentLangLabel');
    if (currentLangLabel && langLabelMap[this.currentLocale]) {
      currentLangLabel.textContent = langLabelMap[this.currentLocale];
    }
  }
}

// 導出全局單例與字典常數
const i18n = new I18nManager();
if (typeof window !== 'undefined') {
  window.i18n = i18n;
  window.I18n = i18n; // 大寫全域名稱，確保 index.html 中的 window.I18n 完美運作
  window.I18N_LOCALES = I18N_LOCALES;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { I18nManager, I18N_LOCALES, i18n, I18n: i18n };
}
